package com.languagefundamentals;

public class TaskDatatypes {
// primitive data types 
	int EmployeeID = 1040;
	byte Employeeage = 35;
	double Employeesalary = 74499.00;
	char Employeegrade = 'A';
	byte Yearsofexperience = 2;
	boolean Employeeisactive = true;
	byte Numberofleaves = 5;
	long Employeephonenumber = 9491088943L;

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		TaskDatatypes t1 = new TaskDatatypes();
		System.out.println(t1.EmployeeID);
		System.out.println(t1.Employeeage);
		System.out.println(t1.Employeesalary);
		System.out.println(t1.Employeegrade);
		System.out.println(t1.Yearsofexperience);
		System.out.println(t1.Employeeisactive);
		System.out.println(t1.Numberofleaves);
		System.out.println(t1.Employeephonenumber);

	}

}

